def orfs(s, strand):
    res = []
    L = len(s)
    for frame in range(3):
        i = frame
        start = None
        while i < L-2:
            codon = s[i:i+3]
            if start is None:
                if codon == "ATG":
                    start = i
            else:
                if codon in stops:
                    res.append((start, i+2, strand, frame, i+2-start+1))
                    start = None
            i += 3
        if start is not None:
            res.append((start, L-1, strand, frame, L-start))
    return res

