seq = "".join(l.strip() for l in open("region.fasta").read().split("\n")[1:])
comp=str.maketrans("ACGT","TGCA")
rc=seq.translate(comp)[::-1]
stops={"TAA","TAG","TGA"}
L=len(seq)

def stopfree(s,strand):
    out=[]
    N=len(s)
    for frame in range(3):
        segs=[]
        i=frame
        cur_start=i
        while i < N-2:
            if s[i:i+3] in stops:
                if i>cur_start: segs.append((cur_start,i-1))
                cur_start=i+3
            i+=3
        if cur_start < N-2 or cur_start<=N-1:
            segs.append((cur_start,N-1))
        for a,b in segs:
            length=b-a+1
            out.append((length,a+1,b+1,strand,frame+1))
    return out

allseg=stopfree(seq,"+")+stopfree(rc,"-")
allseg.sort(reverse=True)
print("longest stop-free stretches (bp, coords on given strand, strand, frame):")
for s in allseg[:12]:
    print(s)
